import json
def try_rule(inp):
    h,w=len(inp),len(inp[0])
    if h==1: c=inp[0].index(2)
    else: return None
    g=[[0]*w for _ in range(w)]
    # 2s: arms from (0,c) to edges, 1s: diagonals inside
    for i in range(w):
        L,R=(c-i,c+i)
        if 0<=L<w: g[i][L]=2
        if 0<=R<w: g[i][R]=2
    # fill between arms with 1 except arm cells
    for i in range(w):
        for j in range(c-i+1,c+i):
            if g[i][j]==0: g[i][j]=1
    return g
